+document.addEventListener('DOMContentLoaded', () => {
+  const triggers = document.querySelectorAll('.faq-trigger');
+
+  triggers.forEach((btn) => {
+    const controlsId = btn.getAttribute('aria-controls');
+    const panel = controlsId ? document.getElementById(controlsId) : btn.closest('h2').nextElementSibling;
+    
+    if (!panel) return;
+
+    // Collapse on init for accessibility best practice (graceful degradation)
+    // The panel starts non-hidden in HTML, so if JS breaks, content remains readable.
+    btn.setAttribute('aria-expanded', 'false');
+    panel.hidden = true;
+
+    btn.addEventListener('click', () => {
+      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
+      
+      // Toggle state
+      btn.setAttribute('aria-expanded', String(!isExpanded));
+      panel.hidden = isExpanded;
+    });
+  });
+});
